const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '1:1' }];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = Math.round(H * 0.56);
    var x0 = Math.round(W * 0.16);
    var x1 = Math.round(W * 0.84);
    var xm = Math.round((x0 + x1) / 2);
    var main = visualSdk.polyline([[x0, y], [x1, y]]);
    var tick = visualSdk.polyline([[xm, y - 20], [xm, y + 20]]);
    var capL = visualSdk.polyline([[x0, y - 12], [x0, y + 12]]);
    var capR = visualSdk.polyline([[x1, y - 12], [x1, y + 12]]);
    return {
      schemaVersion: 1,
      sceneId: 'segment-ratio-1-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'main', commands: main },
        { id: 'tick', commands: tick },
        { id: 'capL', commands: capL },
        { id: 'capR', commands: capR }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'main', fill: 'none', stroke: { width: 3, color: '#26354a' } },
          { type: 'path', pathId: 'tick', fill: 'none', stroke: { width: 3, color: '#26354a' } },
          { type: 'path', pathId: 'capL', fill: 'none', stroke: { width: 3, color: '#26354a' } },
          { type: 'path', pathId: 'capR', fill: 'none', stroke: { width: 3, color: '#26354a' } },
          { type: 'label', contentId: 'c0', anchor: { x: xm, y: y - 36 }, hAlign: 'center', vAlign: 'bottom', color: '#b3261e' }
        ]
      }
    };
  }
};
